<section class="mt-7"><div><h2 class="text-xl font-extrabold">Grow your audience</h2><p class="text-sm text-[#78908c]">Add contacts manually, import a file, or connect a website form.</p></div><div class="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-4"><button onclick="document.getElementById('addDialog').showModal()" class="card p-4 text-left"><i data-lucide="user-plus" class="text-sea"></i><b class="mt-3 block">Web UI</b><span class="text-xs text-[#78908c]">Add one contact</span></button><button onclick="document.getElementById('importInput').click()" class="card p-4 text-left"><i data-lucide="file-spreadsheet" class="text-sea"></i><b class="mt-3 block">CSV / Excel</b><span class="text-xs text-[#78908c]">Upload contacts in bulk</span></button><button onclick="document.getElementById('apiPanel').scrollIntoView({behavior:'smooth'})" class="card p-4 text-left"><i data-lucide="code-2" class="text-sea"></i><b class="mt-3 block">Website API</b><span class="text-xs text-[#78908c]">Connect your forms</span></button><button disabled class="card cursor-not-allowed p-4 text-left opacity-60"><i data-lucide="search" class="text-sea"></i><b class="mt-3 block">Search Leads</b><span class="text-xs text-[#78908c]">Keyword + location · Coming later</span></button></div></section>
