<div class="mt-5 overflow-x-auto"><table class="w-full min-w-[760px] text-left text-sm"><thead class="text-[10px] uppercase text-[#879e9a]"><tr><th class="pb-3">Contact</th><th>Company</th><th>Status</th><th>Source</th><th>Country</th><th>Added</th></tr></thead><tbody class="divide-y divide-[#dbeae7]"><?php foreach($contacts as$c): ?><tr><td class="py-4 font-bold"><?= esc(trim($c['first_name'].' '.$c['last_name'])) ?><p class="text-xs font-normal text-[#78908c]"><?= esc($c['email']) ?></p></td><td><?= esc($c['company']?:'—') ?></td><td><span class="rounded-full bg-[#dff4e9] px-2 py-1 text-xs font-bold text-[#25775f]"><?= esc($c['status']) ?></span></td><td><?= esc(strtoupper($c['source'])) ?></td><td><?= esc($c['country']?:'—') ?></td><td><?= esc(date('M j, Y',strtotime($c['created_at']))) ?></td></tr><?php endforeach ?></tbody></table></div><div class="mt-4"><?= $pager->links() ?></div>
<?php if($imports): ?><div class="mt-6 border-t border-[#dbeae7] pt-5"><h3 class="font-extrabold">Recent imports</h3><div class="mt-3 grid gap-3 md:grid-cols-2 xl:grid-cols-3"><?php foreach($imports as$import): ?><div class="rounded-xl bg-[#e7f2ef] p-3"><div class="flex justify-between gap-3"><p class="truncate text-sm font-bold"><?= esc($import['original_filename']) ?></p><span class="text-xs font-bold uppercase text-sea"><?= esc($import['status']) ?></span></div><p class="mt-2 text-xs text-[#78908c]"><?= number_format($import['created_rows']) ?> created · <?= number_format($import['updated_rows']) ?> updated · <?= number_format($import['invalid_rows']) ?> invalid</p></div><?php endforeach ?></div></div><?php endif ?></section>
<section id="apiPanel" class="card mt-6 p-6"><h3 class="font-extrabold">Website form API</h3><p class="mt-1 text-sm text-[#78908c]">POST JSON to <code><?= esc(base_url('api/v1/contacts')) ?></code> with header <code>X-API-Key</code>. Supported fields: email, first_name, last_name, phone, company, consent_source.</p><form action="<?= workspace_url('contacts/api-keys') ?>" method="post" class="mt-4 flex gap-2"><?= csrf_field() ?><input name="name" class="field max-w-sm" placeholder="Key name, e.g. Website form" required><button class="btn btn-primary">Generate API key</button></form><div class="mt-4 space-y-2"><?php foreach($apiKeys as$key): ?><div class="flex items-center justify-between rounded-xl bg-[#e7f2ef] p-3 text-sm"><span><b><?= esc($key['name']) ?></b> · <?= esc($key['key_prefix']) ?>… · <?= esc($key['status']) ?></span><?php if($key['status']==='active'): ?><form action="<?= workspace_url('contacts/api-keys/'.$key['uuid'].'/revoke') ?>" method="post"><?= csrf_field() ?><button class="text-[#b25d43]">Revoke</button></form><?php endif ?></div><?php endforeach ?></div></section>
<dialog id="addDialog" class="w-full max-w-lg rounded-3xl bg-mist p-6 shadow-2xl backdrop:bg-[#153b39]/30"><div class="flex justify-between"><h3 class="text-xl font-extrabold">Add contact</h3><button onclick="this.closest('dialog').close()"><i data-lucide="x"></i></button></div><form action="<?= workspace_url('contacts/create') ?>" method="post" class="mt-5 space-y-3"><?= csrf_field() ?><input name="email" type="email" required class="field" placeholder="Email address"><div class="grid grid-cols-2 gap-3"><input name="first_name" class="field" placeholder="First name"><input name="last_name" class="field" placeholder="Last name"></div><div class="grid grid-cols-2 gap-3"><input name="company" class="field" placeholder="Company"><input name="job_title" class="field" placeholder="Job title"></div><input name="phone" class="field" placeholder="Phone"><input name="website" type="url" class="field" placeholder="Website"><div class="grid grid-cols-2 gap-3"><input name="city" class="field" placeholder="City"><input name="country" class="field" placeholder="Country"></div><textarea name="notes" class="field" placeholder="Notes"></textarea><button class="btn btn-primary w-full justify-center">Save contact</button></form></dialog>
